export PATH=$PATH:/usr/local/go/bin; go version; osv-scanner --format json -r . > /tmp/osv.json 2>/tmp/osv.err; python3 -c "
import json
d=json.load(open('/tmp/osv.json'))
for r in d['results']:
  print('SRC',r['source']['path'])
  for p in r['packages']:
    pk=p['package']
    for v in p.get('vulnerabilities',[]):
      print(' ',pk.get('ecosystem'),pk.get('name'),pk.get('version'),v['id'],v.get('aliases'),v.get('summary'))
"

export PATH=$PATH:/usr/local/go/bin:~/go/bin; cd . && timeout 600 govulncheck -format json ./... > /tmp/gv.json 2>/tmp/gv.err; echo $?; tail -5 /tmp/gv.err; python3 -c "
import json
dec=json.JSONDecoder(); s=open('/tmp/gv.json').read(); i=0; ids=set(); called=set()
while i<len(s):
  s2=s[i:].lstrip();
  if not s2: break
  o,n=dec.raw_decode(s2); i=len(s)-len(s2)+n
  if 'finding' in o:
    f=o['finding']; ids.add(f['osv'])
    if f['trace'] and f['trace'][0].get('function'): called.add(f['osv'])
print('all',sorted(ids)); print('called',sorted(called))
"

